import {parseSale,quantityFor,settlePayment,normalizeVoice,correctSale} from './sale-language.js';
export function createSaleVoice(ctx){
 const {esc,money,notice}=ctx;let opened=false,transcript='',draft=null,origin=null,replacing=false,listening=false,request=null,recognizer=null,timer=null,sequence=0,busy=false,correction=false,holder={dataset:{}};
 const products=()=>ctx.products();
 function cancel(){const id=request;request=null;listening=false;clearTimeout(timer);if(id&&window.AndroidHost?.cancelSaleVoice)window.AndroidHost.cancelSaleVoice(id);if(recognizer){recognizer.abort();recognizer=null;}}
 function reset(){cancel();opened=false;transcript='';draft=null;origin=null;replacing=false;holder={dataset:{}};}
 function interpret(){const s=ctx.state();origin={shift:s.shift?.id,store:s.storeId};draft=parseSale(transcript,products());opened=true;replacing=false;}
 function plan(){const errors=[...(draft?.errors||[])],s=ctx.state(),catalogue=products(),map=new Map();let total=0;
  if(!draft)return {errors:['Primero dicta o escribe la venta.'],lines:[],total:0,pay:{}};
  if(!s.shift||origin?.shift!==s.shift.id||origin?.store!==s.storeId)errors.push('Cambió la tienda o el turno. Vuelve a interpretar la venta.');
  const store=s.data.stores.find(x=>x.id===s.storeId)?.name;if(draft.store&&normalizeVoice(store)!==draft.store)errors.push(`La frase menciona ${draft.store}, pero estás en ${store}. Selecciona la tienda correcta antes de continuar.`);
  for(const item of draft.items){const p=catalogue.find(p=>p.id===item.productId);if(!p){errors.push(`Elige el producto para «${item.phrase}».`);continue;}const qty=quantityFor(item,p),step=Number(p.quantity_step||1);if(!Number.isFinite(qty)||qty<=0||Math.abs(qty/step-Math.round(qty/step))>1e-7){errors.push(`Revisa la cantidad de ${p.name}: ${p.unit==='ciento'?'se vende en cientos, de 0,5 en 0,5':'usa unidades enteras'}.`);continue;}map.set(p.id,(map.get(p.id)||0)+qty);total+=Math.round(Math.round(p.voicePrice*100)*qty)/100;}
  for(const [id,qty]of map){const p=catalogue.find(p=>p.id===id);if(qty>p.voiceStock)errors.push(`Stock insuficiente de ${p.category} · ${p.name}. Disponible: ${p.voiceStock} ${p.unit}.`);}
  const discount=Number(draft.payment.discount||0);if(!Number.isFinite(discount)||discount<0||discount>total||Math.abs(discount*100-Math.round(discount*100))>1e-7)errors.push('Revisa el descuento.');total=Math.round((total-discount)*100)/100;
  if(draft.payment.declaredTotal!==null&&Math.abs(draft.payment.declaredTotal-total)>.001)errors.push('El total mencionado no coincide con los precios del turno. Revisa los productos o el descuento.');
  const pay=settlePayment(total,draft.payment.mode,draft.payment.received,draft.payment.yape);if(pay.error)errors.push(pay.error);if(ctx.cartCount()&&!replacing)errors.push('Ya tienes una venta en el carrito. Termínala o marca que deseas reemplazarla.');
  return {errors:[...new Set(errors)],lines:[...map].map(([product_id,qty])=>({product_id,qty})),total,pay,discount,payment:{...draft.payment},transcript};
 }
 function summary(){const p=plan();return `<div class="voice-summary"><div><span>Total del catálogo</span><strong>${money(p.total)}</strong></div>${!p.pay.error?`<div><span>Ingreso en efectivo</span><strong>${money(p.pay.cash)}</strong></div><div><span>Ingreso por Yape</span><strong>${money(p.pay.yape)}</strong></div><div class="voice-change"><span>Vuelto a entregar</span><strong>${money(p.pay.change)}</strong></div>`:''}</div>${p.errors.length?`<div class="warn" role="status">${p.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:''}`;}
 function choices(candidates,i){const list=products();return candidates.slice(0,4).map(c=>{const p=list.find(p=>p.id===c.id);return p?`<button type="button" class="secondary" data-voice-choice="${i}" data-product="${p.id}">${esc(p.category)} · ${esc(p.name)}</button>`:'';}).join('')+(candidates.length>4?'<small>Escribe más para acotar los resultados.</small>':'');}
 function review(){if(!draft)return '';const catalogue=products();return `<div id="voice-review"><h3>Revisar lo interpretado</h3>${draft.items.map((item,i)=>{const p=catalogue.find(p=>p.id===item.productId);return `<div class="voice-item"><small>Oí: ${esc(item.phrase)}</small><strong class="voice-product-name">${p?esc(p.category+' · '+p.name):'Elige el producto'}</strong><label>Buscar o corregir producto<input data-voice-search="${i}" type="search" placeholder="Nombre o categoría"></label><div class="voice-choices" data-voice-choices="${i}">${choices(item.candidates,i)}</div><label>Cantidad <span data-voice-unit>${p?`(${esc(p.unit)})`:''}</span><input type="number" inputmode="decimal" data-voice-qty="${i}" min="${p?.quantity_step||.5}" step="${p?.quantity_step||.5}" value="${p?quantityFor(item,p):item.amount}"></label>${!p&&item.candidates.length>1?'<small data-voice-choice-note>Hay varios productos posibles. Elige cuál se vendió.</small>':''}</div>`;}).join('')}<div class="fields"><label>Medio de pago<select data-voice-payment="mode">${[['','Elige…'],['cash','Efectivo'],['yape','Yape'],['mixed','Efectivo y Yape']].map(([v,l])=>`<option value="${v}" ${draft.payment.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Efectivo entregado por el cliente<input type="number" inputmode="decimal" min="0" step=".01" data-voice-payment="received" value="${draft.payment.received??''}" placeholder="Opcional si paga exacto"></label><label>Yape recibido<input type="number" inputmode="decimal" min="0" step=".01" data-voice-payment="yape" value="${draft.payment.yape??''}" placeholder="Vacío = total, si paga solo Yape"></label><label>Descuento (S/)<input type="number" inputmode="decimal" min="0" step=".01" data-voice-payment="discount" value="${draft.payment.discount??0}"></label></div>${ctx.cartCount()?'<label class="check"><input type="checkbox" data-voice-replace><span>Reemplazar la venta que tengo en el carrito.</span></label>':''}<div id="voice-review-summary">${summary()}</div><div class="actions"><button type="button" data-voice-confirm ${plan().errors.length||busy?'disabled':''}>${busy?'Guardando…':'Confirmar y guardar venta'}</button><button type="button" class="secondary" data-voice-apply ${plan().errors.length||busy?'disabled':''}>Editar en carrito</button><button type="button" class="secondary" data-voice-correct>Dictar corrección</button></div><label>Corrección escrita<input data-voice-correction placeholder="cambia a dos / quita la vela / pagó por Yape"></label><button type="button" class="secondary" data-voice-correct-text>Aplicar corrección</button></div>`;}
 function update(){const target=document.querySelector('#voice-review-summary');if(target)target.innerHTML=summary();document.querySelectorAll('[data-voice-apply],[data-voice-confirm]').forEach(button=>button.disabled=busy||plan().errors.length>0);}
 function view(){if(!opened)return '';return `<section class="card voice-sale" id="voice-sale-panel"><div class="voice-heading"><div><h2>Venta por voz</h2></div><button type="button" class="secondary" data-voice-open aria-expanded="${opened}">${opened?'Cerrar':'Dictar venta'}</button></div>${opened?`<div class="voice-body"><button type="button" data-voice-start aria-pressed="${listening}">${listening?'■ Cancelar dictado':'🎙 Dictar venta'}</button><p class="small muted" role="status">${listening?'Escuchando…':''}</p><label>Frase dictada o escrita<textarea data-voice-transcript maxlength="1500" placeholder="También puedes escribir la venta aquí.">${esc(transcript)}</textarea></label><button type="button" class="secondary" data-voice-interpret>Interpretar frase</button>${review()}</div>`:''}</section>`;}
 function result(id,text,error){if(id!==request)return;request=null;listening=false;clearTimeout(timer);if(!document.querySelector('#voice-sale-panel'))return;if(error){notice(error,true);ctx.render();return;}if(correction){try{draft=correctSale(draft,text,products());transcript+='; corrección: '+text;holder={dataset:{}};}catch(e){notice(e.message,true);}correction=false;}else{transcript=String(text).slice(0,1500);interpret();}ctx.render();document.querySelector('#voice-review')?.scrollIntoView({behavior:'smooth',block:'start'});}
 window.charitoSaleVoiceResult=result;
 function start(){if(listening){cancel();ctx.render();return;}opened=true;listening=true;request=String(++sequence);const id=request;ctx.render();timer=setTimeout(()=>{if(request===id){cancel();notice('El dictado tardó demasiado. Vuelve a intentarlo o escribe la frase.',true);ctx.render();}},60000);
  if(window.AndroidHost?.startSaleVoice){window.AndroidHost.startSaleVoice(id);return;}
  const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){result(id,'','Este navegador no admite dictado. Usa la APK actualizada o escribe la frase.');return;}
  try{recognizer=new Speech();recognizer.lang='es-PE';recognizer.interimResults=false;recognizer.maxAlternatives=1;recognizer.onresult=e=>result(id,e.results[0][0].transcript,'');recognizer.onerror=e=>result(id,'',e.error==='not-allowed'?'Permite el micrófono del sitio para dictar.':'No se pudo reconocer la voz. Reintenta o escribe la frase.');recognizer.onend=()=>{if(request===id)result(id,'','No se escuchó una frase. Inténtalo de nuevo.');};recognizer.start();}catch{result(id,'','No se pudo iniciar el micrófono. Puedes escribir la frase.');}
 }
 async function click(b){if(b.hasAttribute('data-voice-confirm')){if(busy)return true;const p=plan();if(p.errors.length)throw Error(p.errors[0]);busy=true;update();try{await ctx.confirm(p,holder);}finally{busy=false;update();}return true;}if(b.hasAttribute('data-voice-correct')){correction=true;start();return true;}if(b.hasAttribute('data-voice-correct-text')){draft=correctSale(draft,document.querySelector('[data-voice-correction]').value,products());holder={dataset:{}};ctx.render();return true;}if(b.hasAttribute('data-voice-choice')){const item=draft.items[Number(b.dataset.voiceChoice)];item.productId=b.dataset.product;delete item.override;holder={dataset:{}};ctx.render();return true;}if(b.hasAttribute('data-voice-open')){if(opened){cancel();opened=false;ctx.render();}else start();return true;}if(b.hasAttribute('data-voice-start')){start();return true;}if(b.hasAttribute('data-voice-interpret')){cancel();interpret();ctx.render();return true;}if(b.hasAttribute('data-voice-apply')){const p=plan();if(p.errors.length)throw Error(p.errors[0]);ctx.apply(p);reset();ctx.render();ctx.openCheckout?.();return true;}return false;}
 function input(e){const t=e.target;if(t.hasAttribute('data-voice-search')){if(e.type!=='input')return true;const i=Number(t.dataset.voiceSearch),q=normalizeVoice(t.value).split(/\s+/).filter(Boolean),found=products().filter(p=>q.every(w=>normalizeVoice(`${p.name} ${p.category} ${p.sku}`).includes(w))).map(p=>({id:p.id}));document.querySelector(`[data-voice-choices="${i}"]`).innerHTML=choices(found,i);return true;}if(t.hasAttribute('data-voice-transcript')){transcript=t.value;draft=null;document.querySelector('#voice-review')?.remove();return true;}if(t.hasAttribute('data-voice-product')){if(e.type!=='change')return true;const item=draft.items[Number(t.dataset.voiceProduct)];item.productId=t.value;delete item.override;const p=products().find(p=>p.id===t.value),input=t.closest('.voice-item').querySelector('[data-voice-qty]');const note=t.closest('.voice-item').querySelector('[data-voice-choice-note]');if(note)note.textContent=p?'Producto elegido para esta venta.':'Elige cuál se vendió.';if(p){t.closest('.voice-item').querySelector('[data-voice-unit]').textContent=`(${p.unit})`;input.value=quantityFor(item,p);input.step=p.quantity_step;input.min=p.quantity_step;}update();return true;}if(t.hasAttribute('data-voice-qty')){draft.items[Number(t.dataset.voiceQty)].override=Number(t.value);update();return true;}if(t.hasAttribute('data-voice-payment')){const key=t.dataset.voicePayment;draft.payment[key]=key==='mode'?t.value:t.value===''?null:Number(t.value);update();return true;}if(t.hasAttribute('data-voice-replace')){replacing=t.checked;update();return true;}return false;}
 return {snapshot:()=>({opened,transcript,draft,origin,replacing,holder}),restore:raw=>{if(raw){opened=!!raw.opened;transcript=raw.transcript||'';draft=raw.draft;origin=raw.origin;replacing=!!raw.replacing;holder=raw.holder||{dataset:{}};}},view,click,input,reset,cancel,isListening:()=>listening};
}
